use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::Path;

fn prior() -> HashMap<String, u32> {
    let mut out = HashMap::new();
    if let Ok(raw) = fs::read_to_string("/app/tidearc/lastgood.rec") {
        for line in raw.lines() {
            let p: Vec<&str> = line.split('\t').collect();
            if p.len() >= 2 {
                if let Ok(seq) = p[0].trim().parse::<u32>() {
                    out.insert(p[1].trim().to_string(), seq);
                }
            }
        }
    }
    out
}

pub fn rib_c(pairs: &[(String, u64)], root: Option<&str>) -> Result<Vec<String>, i32> {
    if let Some(r) = root {
        let wanted = fs::canonicalize("/app/dropwell").map_err(|_| 1)?;
        let got = fs::canonicalize(r).map_err(|_| 1)?;
        if got != wanted { return Err(1); }
    }
    if pairs.is_empty() { return Err(1); }
    let old = prior();
    let mut seen = HashSet::new();
    let mut existing = Vec::new();
    let mut fresh = Vec::new();
    for (path, stamp) in pairs {
        let name = match Path::new(path).file_name().and_then(|s| s.to_str()) {
            Some(s) => s.to_string(), None => return Err(1)
        };
        if !seen.insert(name.clone()) { return Err(1); }
        if let Some(&seq) = old.get(&name) {
            existing.push((seq, path.clone()));
        } else {
            let m = crate::parse::load(path);
            fresh.push((*stamp, m.guid, m.companion, name, path.clone()));
        }
    }
    existing.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    fresh.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)).then_with(|| a.2.cmp(&b.2)).then_with(|| a.3.cmp(&b.3)));
    let mut out: Vec<String> = existing.into_iter().map(|x| x.1).collect();
    out.extend(fresh.into_iter().map(|x| x.4));
    Ok(out)
}
